INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3f5187a1-1635-487e-89f2-c17d2265078c', 'profile-1780169301356', 'family_adventure', 1780513200000, NULL, '[]'::jsonb, 'Robbie went to the zoo on a field trip and had a lot of fun.', '[]'::jsonb, 'voice', 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', NULL, NULL, 'positive', '[]'::jsonb, 0, 1780710076711, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('fb6e89bb-3f60-4b0e-a461-26611fabf623', 'profile-1780169301356', 'school_incident', 1780723452298, NULL, '[]'::jsonb, 'Misbehaved with his friend Albie and clogged a toilet at school.', '[]'::jsonb, 'voice', 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', NULL, '🚽', 'negative', '[]'::jsonb, 0, 1780723452387, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('760f947f-6a1d-4142-aff5-fe3fb56475a0', 'profile-1780169301356', 'naughty', 1780807599983, NULL, '[]'::jsonb, 'Denied making a mess in playroom', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '😈', 'negative', '[]'::jsonb, 0, 1780807600073, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('225bd1d1-6564-4150-8d60-df85e695cb8f', 'profile-1780169301356', 'great_day', 1781071166292, NULL, '[]'::jsonb, 'Had a really good day', '[]'::jsonb, 'voice', 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', NULL, '🐦‍🔥', 'positive', '[]'::jsonb, 0, 1781071166376, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f8a09a32-add5-474c-91e8-c8cd1db397e0', 'profile-1780169301356', 'great_day', 1781155856600, NULL, '[]'::jsonb, 'Had a good day', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '🌟', 'positive', '[]'::jsonb, 0, 1781155856694, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('d689a15c-ec5b-409e-9ea2-837161c0705e', 'profile-1780169301356', 'video_games', 1781240356304, NULL, '[]'::jsonb, 'Played video games with teacher (Mr. Nick)', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '🎮', 'neutral', '[]'::jsonb, 0, 1781240356400, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ee0b62d0-556e-4acb-b831-0fbdfc2036a7', 'profile-1780169301356', 'parent_out_of_town', 1781290800000, NULL, '[]'::jsonb, 'Mom in South Carolina', '[]'::jsonb, 'quick-tap', NULL, 'Parent(s) Away', NULL, NULL, '[]'::jsonb, 0, 1781420836047, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('28e9074a-16c7-4fe3-a4e3-0abdd00b2998', 'profile-1780169301356', 'parent_out_of_town', 1781419993112, NULL, '[]'::jsonb, 'Mom in South Carolina', '[]'::jsonb, 'quick-tap', NULL, 'Parent(s) Away', NULL, NULL, '[]'::jsonb, 0, 1781419993112, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9350b0e2-2af1-495b-9f24-222b41779e51', 'profile-1780169301356', 'good_sleep', 1781495798978, NULL, '[]'::jsonb, 'Slept in until 8am', '[]'::jsonb, 'quick-tap', NULL, 'Good Sleep', NULL, NULL, '[]'::jsonb, 0, 1781495798979, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4bb10a7f-d71d-4b9b-b6d1-45952de6e200', 'profile-1780169301356', 'overwhelm', 1781636400000, NULL, '[]'::jsonb, 'Felt sad about broken friendship', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '😢', 'negative', '[]'::jsonb, 0, 1781756594992, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('1d27b20c-3b31-48f0-9bb7-fe6d97218825', 'profile-1780169301356', 'custom', 1781757072420, NULL, '[]'::jsonb, 'Robbie was still heartbroken about his fractured friendship with Albie', '[]'::jsonb, 'custom', NULL, 'Sad', '😞', 'neutral', '[]'::jsonb, 0, 1781757072420, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6f5e7faa-86be-49d7-9b52-6fb8ee039807', 'profile-1780169301356', 'great_day', 1781809200000, NULL, '[]'::jsonb, 'Woke up in a good mood', '[]'::jsonb, 'voice', 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', NULL, '🌟', 'positive', '[]'::jsonb, 0, 1781931282732, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('55e195b1-1e92-43cc-8009-e4982ed325a1', 'profile-1780169301356', 'stayed_home', 1781930549768, NULL, '[]'::jsonb, 'Stayed at home with the nanny', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '🏠', 'neutral', '[]'::jsonb, 0, 1781930549858, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c1ad174d-d759-4f76-bd3f-a1989dbf119d', 'profile-1780169301356', 'wet_bed', 1780379061782, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Wet Bed', NULL, NULL, '[]'::jsonb, 1, 1780379061783, 0) ON CONFLICT (id) DO NOTHING;
