INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b9ad2761-4f8a-4f8d-9083-55416c10a651', 'profile-1780169301356', 'good_dinner', 1780513200000, NULL, '[]'::jsonb, 'He had a nice dinner of salad and a hot dog.', '[]'::jsonb, 'voice', 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', NULL, NULL, 'positive', '[]'::jsonb, 3, 1780710076712, 0) ON CONFLICT (id) DO NOTHING;
