INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0782a036-2946-4980-9856-b59a3453bf7e', 'profile-1780169301356', 'good_dinner', 1781240356304, NULL, '[]'::jsonb, 'Chicken balls, nectarines, cauliflower ', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '😋', 'positive', '[]'::jsonb, 3, 1781240356409, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('1253e4d0-1801-4d5d-aec3-01dffaa2a8be', 'profile-1780169301356', 'sugar', 1781290800000, NULL, '[]'::jsonb, 'Had a lot of popsicles', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🍬', 'neutral', '[]'::jsonb, 3, 1781420804055, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3c9459e7-8d04-41ed-92ed-da277b765b2d', 'profile-1780169301356', 'conflict', 1781495794604, NULL, '[]'::jsonb, 'Had conflict over cleaning', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '⚡', 'negative', '[]'::jsonb, 3, 1781495794701, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9bd8b47b-4811-458d-a0c9-f44028699481', 'profile-1780169301356', 'good_dinner', 1781636400000, NULL, '[]'::jsonb, 'Ate a good dinner', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '😋', 'positive', '[]'::jsonb, 3, 1781756594987, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9b1490c1-b9be-482f-8a7d-0fa238888899', 'profile-1780169301356', 'toilet_issue', 1781756264543, NULL, '[]'::jsonb, 'Peed pants three times during playdate', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '🚽', 'negative', '[]'::jsonb, 3, 1781756264646, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('da771f54-d5c1-4553-b79b-68958d6e59ae', 'profile-1780169301356', 'helpful', 1781930549768, NULL, '[]'::jsonb, 'Cleaned up after playing', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '🤝🏻', 'positive', '[]'::jsonb, 3, 1781930549865, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('11c4e5b3-c853-412e-a72c-1ba89d7896cc', 'profile-1780169301356', 'medication', 1780426800000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 4, 1780726179857, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e17240e7-9110-4605-bb94-7f70d3ab49f5', 'profile-1780169301356', 'sibling_harmony', 1780513200000, NULL, '[]'::jsonb, 'He pushed his sister on the swing after dinner.', '[]'::jsonb, 'voice', 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', NULL, NULL, 'positive', '[]'::jsonb, 4, 1780710076713, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('7e1aae80-e627-4bd3-ac8d-2df174146eb9', 'profile-1780169301356', 'chores', 1780599600000, NULL, '[]'::jsonb, 'Cleaned his room before going to bed.', '[]'::jsonb, 'voice', 'Robbie had a good day, he went to school, got dressed on his own, then when he came home he played soccer with dad and built blocks with his brother Andy. He cleaned up his room before going to bed and took his medicine.', NULL, NULL, 'positive', '[]'::jsonb, 4, 1780708957385, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b4a958b7-9773-4ae5-b632-a06dcd62925c', 'profile-1780169301356', 'watched_tv', 1780723452298, NULL, '[]'::jsonb, 'Watched Bluey for 1+ hours before bed.', '[]'::jsonb, 'voice', 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', NULL, '📺', 'neutral', '[]'::jsonb, 4, 1780723452391, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8249a577-3df2-457d-8c47-ca1f130402c2', 'profile-1780169301356', 'family_adventure', 1780807599983, NULL, '[]'::jsonb, 'Went shopping for art supplies', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🏕️', 'positive', '[]'::jsonb, 4, 1780807600077, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('cbbd54d5-5129-4a36-a267-cbb5cb241ebe', 'profile-1780169301356', 'helpful', 1781071187743, NULL, '[]'::jsonb, 'Very well behaved in the evening', '[]'::jsonb, 'quick-tap', NULL, 'Helpful', NULL, NULL, '[]'::jsonb, 4, 1781071187744, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3facfe50-dbeb-457d-88df-d8c296b95237', 'profile-1780169301356', 'sibling_harmony', 1781155856600, NULL, '[]'::jsonb, 'Was mild mannered with siblings', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '🫂', 'positive', '[]'::jsonb, 4, 1781155856698, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ae733dc4-0a46-4720-a3fd-5556eb6d058a', 'profile-1780169301356', 'helpful', 1781241084483, NULL, '[]'::jsonb, 'Volunteered to take a bath', '[]'::jsonb, 'quick-tap', NULL, 'Helpful', NULL, NULL, '[]'::jsonb, 4, 1781241084486, 0) ON CONFLICT (id) DO NOTHING;
