INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('80e89b9e-e11c-4655-b411-41d942537742', 'profile-1780169301356', 'good_sleep', 1780723452298, NULL, '[]'::jsonb, 'Went down easily to sleep with Andy in the same room.', '[]'::jsonb, 'voice', 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', NULL, '😴', 'positive', '[]'::jsonb, 5, 1780723452392, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('5547fcc8-8b60-4221-a92f-3a046bd3945d', 'profile-1780169301356', 'bad_language', 1780807599983, NULL, '[]'::jsonb, 'Used potty language at dinner', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🤬', 'negative', '[]'::jsonb, 5, 1780807600078, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f8d9f167-3e48-49f2-848c-b59bedd63e63', 'profile-1780169301356', 'medication', 1781071166292, NULL, '[]'::jsonb, 'Had medicine before bed', '[]'::jsonb, 'voice', 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', NULL, 'neutral', 'neutral', '[]'::jsonb, 5, 1781071166378, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4dd17d9b-2c10-4bee-89fd-71562f0c30af', 'profile-1780169301356', 'watched_tv', 1781155856600, NULL, '[]'::jsonb, 'Earned TV time in the evening', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '📺', 'neutral', '[]'::jsonb, 5, 1781155856699, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9b83bcd9-daeb-43ee-ad36-beab92b17b10', 'profile-1780169301356', 'watched_tv', 1781240356304, NULL, '[]'::jsonb, 'Watched TV after dinner', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '📺', 'neutral', '[]'::jsonb, 5, 1781240356411, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('62198226-855e-45a9-9d30-17ae3ff85194', 'profile-1780169301356', 'drew_comics', 1781290800000, NULL, '[]'::jsonb, 'Drew comics at home', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🦸', 'neutral', '[]'::jsonb, 5, 1781420804057, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('33f06b93-a37a-48d7-83d4-b44117114545', 'profile-1780169301356', 'shutdown', 1781495794604, NULL, '[]'::jsonb, 'Shut down in room', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🔇', 'negative', '[]'::jsonb, 5, 1781495794702, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c4f9b3c8-0571-45aa-afd7-660d93c5ded8', 'profile-1780169301356', 'custom', 1781636400000, NULL, '[]'::jsonb, 'Made an impressive block structure with his matchbox cars', '[]'::jsonb, 'custom', NULL, 'Creativity', '🚗', 'positive', '[]'::jsonb, 5, 1781756656722, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('fd9832bd-cb72-414c-afb1-350de95bb5be', 'profile-1780169301356', 'good_dinner', 1781756264543, NULL, '[]'::jsonb, 'Ate a good dinner', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '😋', 'positive', '[]'::jsonb, 5, 1781756264648, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8caa862b-6725-47cc-8a1b-4ae23b2b1e73', 'profile-1780169301356', 'playdate', 1781809200000, NULL, '[]'::jsonb, 'Played with neighbors in basement', '[]'::jsonb, 'voice', 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', NULL, '👫', 'positive', '[]'::jsonb, 5, 1781931282737, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ee79b6f5-f4fa-4b03-84af-be9118479d46', 'profile-1780169301356', 'fast_food', 1781930549768, NULL, '[]'::jsonb, 'Ate fast food at Wendy''s', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '🍟', 'neutral', '[]'::jsonb, 5, 1781930549867, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4688bb36-7413-42b2-959d-dd1ede9cbf61', 'profile-1780169301356', 'medication', 1780723577638, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 6, 1780723577639, 0) ON CONFLICT (id) DO NOTHING;
