INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6e7b1dc5-a119-4c8f-bc2b-4bc5855b176e', 'profile-1780169301356', 'bounceback', 1780807599983, NULL, '[]'::jsonb, 'Had a quiet evening after meltdowns', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🐦‍🔥', 'positive', '[]'::jsonb, 7, 1780807600080, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('10da67bd-f4a8-432e-a515-0d8a3e2a29db', 'profile-1780169301356', 'good_sleep', 1781155856600, NULL, '[]'::jsonb, 'Went down for bed fairly easily', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '😴', 'positive', '[]'::jsonb, 7, 1781155856700, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9c457cbb-7792-479b-87b1-f4432435415d', 'profile-1780169301356', 'medication', 1781240356304, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '💊', 'neutral', '[]'::jsonb, 7, 1781240356412, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('643e3f79-7f9f-4017-800b-0d0869634eeb', 'profile-1780169301356', 'bounceback', 1781290800000, NULL, '[]'::jsonb, 'Recovered quickly from dysregulation', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🐦‍🔥', 'positive', '[]'::jsonb, 7, 1781420804058, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ccd12518-22d0-4d2c-bddc-48efc2b1a3b8', 'profile-1780169301356', 'family_adventure', 1781495794604, NULL, '[]'::jsonb, 'Picked up mom from the airport', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🏕️', 'positive', '[]'::jsonb, 7, 1781495794704, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e77734bc-3766-4849-adba-2fd279fc69c7', 'profile-1780169301356', 'medication', 1781636400000, NULL, '[]'::jsonb, 'Took medicine before bed', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '💊', 'neutral', '[]'::jsonb, 7, 1781756594991, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3c165be3-9a2c-4542-85e6-bce642b2941f', 'profile-1780169301356', 'medication', 1781756277047, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 7, 1781756277048, 0) ON CONFLICT (id) DO NOTHING;
