INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('7340f8d8-2436-46e8-8c1c-1ecc98ebd5d6', 'profile-1780169301356', 'medication', 1781930549768, NULL, '[]'::jsonb, 'Took medicine before sleep', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '💊', 'neutral', '[]'::jsonb, 7, 1781930549868, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('444e7b78-fa60-459b-8366-7e44a394aa97', 'profile-1780169301356', 'good_dinner', 1780724096940, NULL, '[]'::jsonb, 'Carrots and pasta + popsicle for dessert', '[]'::jsonb, 'quick-tap', NULL, 'Good Dinner', NULL, NULL, '[]'::jsonb, 8, 1780724096941, 0) ON CONFLICT (id) DO NOTHING;
