INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('7e50f667-519e-4ab3-9324-1315972ce009', 'profile-1780169301356', 'messy', 1781586006069, NULL, '[]'::jsonb, 'Built a pillow fort', '[]'::jsonb, 'voice', 'Robbie had a fairly volatile day slash evening. He built a pillow fort in the living room after school, which is a toy structure he is notorious for not cleaning after. When asked to tidy it up before dinner, he had a meltdown and stormed off to his room. He came down shortly thereafter and had a good pleasant dinner. Mom tried to get him to clean again after dinner, but he was pretty lazy and uncooperative and did a half-hearted job. Mom had some good bonding time with him in his room later in the evening. He got to bed without issue and took 2mg of guanfacine before sleep.', NULL, '🫗', 'negative', '[]'::jsonb, NULL, 1781586006155, 0) ON CONFLICT (id) DO NOTHING;
