INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6bd1122b-8e40-4c5d-af11-0c3d81a83254', 'profile-1780169301356', 'mom_bonding', 1782103282339, NULL, '[]'::jsonb, 'Collaborated on Father''s Day gifts', '[]'::jsonb, 'voice', 'Good day for Robbie. He woke up on Father''s Day after sleeping in and collaborated with his mom on Father''s Day gifts and baking of a special treat for dad. He stayed home with Hyanna in the morning and I didn''t hear of any incidents of bad behavior. In the afternoon he went outside in the wading pool in the backyard with his brother and sister and then the whole family went to see a movie in Toy Story 5 in the late afternoon. Afterwards the whole family went to a Thai restaurant and we got home with enough time for him to bathe before bed. He took his medicine and went down without a struggle.', NULL, '👩🏼', 'positive', '[]'::jsonb, NULL, 1782103282427, 0) ON CONFLICT (id) DO NOTHING;
