INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('f3f8fc57-210a-44d3-97f4-abe64225c036', 'profile-1780169301356', 1782277803997, 'Robbie had a fantastic day again. He woke up in a good mood and had a good breakfast and was helpful and plucky about getting out of the house on time for camp. He attended camp with a good attitude and had smiles for his counselors who remembered him. At pickup he had ice cream and played nicely with his siblings. He did cheat a bit at chess but was funny about it. When we got home he drew comics and was very interested in the reward system that his parents devised for him. He told me in detail about his day to earn rewards and said he''d made a new friend Anthony. He had a good dinner then got to earn 30 minutes of screen time, which was a game that he played together with mom. Then he went to bed with no resistance, maybe his best day ever.', 1782277803997, 'voice', 1782277803999, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('d3b81373-c466-470d-8715-5fc660b0605d', 'profile-1780169301356', 1782154800000, 'Robbie was fantastic today, traveling with his mom and siblings to Colorado. He was helpful with his siblings across two airplanes. He sat next to strangers on the flights, even though he was scared to. He ate a good dinner, was polite to his grandmother. He was a wonderful boy today. He made comics and drew and read, watched iPad, and played games on the airplane. He did miss his dose of medicine.', 1782154800000, 'voice', 1782276401053, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('96b7018e-c60b-4135-93ec-bffc0ed8dd33', 'profile-1780169301356', 1782103282339, 'Good day for Robbie. He woke up on Father''s Day after sleeping in and collaborated with his mom on Father''s Day gifts and baking of a special treat for dad. He stayed home with Rayanna in the morning and I didn''t hear of any incidents of bad behavior. In the afternoon he went outside in the wading pool in the backyard with his brother and sister and then the whole family went to see a movie in Toy Story 5 in the late afternoon. Afterwards the whole family went to a Thai restaurant and we got home with enough time for him to bathe before bed. He took his medicine and went down without a struggle.', 1782103282339, 'voice', 1782103282339, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('ac37bb82-a3a0-4faf-8637-e33bc0200168', 'profile-1780169301356', 1781982000000, 'Robbie had a decent day. He slept in until around 8am and stayed home with the nanny throughout the morning. He seemed relatively well behaved. In the afternoon, he played in the new wading pool that we bought for the backyard. Later in the day, he played with his siblings and they all watched Bluey together. Robbie also collaborated on a Father''s Day gift with his brother and sister. He got to bed easily and took his medicine. A fairly uneventful and pleasant day.', 1781982000000, 'voice', 1782103181295, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('61390545-eb5a-43a6-99c0-00ac84a2e401', 'profile-1780169301356', 1781930549768, 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', 1781930549768, 'voice', 1781930549771, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('df2e2ac7-94a7-4b5a-b506-bbe4df94ba02', 'profile-1780169301356', 1781809200000, 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', 1781809200000, 'voice', 1781931282642, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('952494cb-8b57-452b-918a-0a4c6de84626', 'profile-1780169301356', 1781756264543, 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', 1781756264543, 'voice', 1781756264545, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('c16f7141-95ee-4789-abb4-f020b77f82aa', 'profile-1780169301356', 1781636400000, 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', 1781636400000, 'voice', 1781756594894, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('8cfb4ea1-a125-49a7-a099-cbc1bfb122f9', 'profile-1780169301356', 1781586006069, 'Robbie had a fairly volatile day slash evening. He built a pillow fort in the living room after school, which is a toy structure he is notorious for not cleaning after. When asked to tidy it up before dinner, he had a meltdown and stormed off to his room. He came down shortly thereafter and had a good pleasant dinner. Mom tried to get him to clean again after dinner, but he was pretty lazy and uncooperative and did a half-hearted job. Mom had some good bonding time with him in his room later in the evening. He got to bed without issue and took 2mg of guanfacine before sleep.', 1781586006069, 'voice', 1781586006071, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('8a460798-4685-4b77-90f0-0645a1f9a89b', 'profile-1780169301356', 1781495794604, 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', 1781495794604, 'voice', 1781495794606, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('7544b660-d0c7-4aba-87aa-d3e8497a5640', 'profile-1780169301356', 1781420255446, 'Mom, out of town in South Carolina, woke up at 7 and was fairly well-behaved during the morning when he stayed home with our babysitter, Hyanna. Did baseball bonding time with Dad in the backyard in the late morning. He was a bit unkind with Andy here and there, but nothing egregious. Did comics. After Daisy awoke from her nap, we went to Michael''s to get balloons and tchotchkes. Robbie had an excellent dinner and ate all of his chicken, apples, and carrots. The kids watched TV in the evening before bed and Robbie had two bowls of cereal as he was still hungry after a big dinner. Took two milligrams of guanfacin.', 1781420255446, 'voice', 1781420255448, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('afa3a4f3-9389-41e0-b086-89dace6b691c', 'profile-1780169301356', 1781290800000, 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', 1781290800000, 'voice', 1781420803963, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('3cd7ebe1-002f-4349-9baa-dd29d2c764c8', 'profile-1780169301356', 1781240356304, 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', 1781240356304, 'voice', 1781240356306, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('22d49edd-d69b-454d-a41a-9edd262236e0', 'profile-1780169301356', 1781155856600, 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', 1781155856600, 'voice', 1781155856602, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('6d659d7e-7412-4104-a09d-ebf62027e923', 'profile-1780169301356', 1781071166292, 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', 1781071166292, 'voice', 1781071166292, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('9d64a91d-6660-40f0-bf71-8d8c919fd2cc', 'profile-1780169301356', 1780945200000, 'Good day. Robbie was on his best behavior as he wanted to be rewarded with toy pranks. He and dad had more good child-directed interaction time playing baseball in the backyard. He was sweet with his sister in the evening, carrying her around as she giggled. He had a half-hearted dinner, which he had more of later in the night before bed since he got hungry. He watched the Knicks basketball game as the family went to bed without any issue, took his medicine.', 1780945200000, 'voice', 1781067366145, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('78bbdce4-77ec-4e90-9770-6869a9731af8', 'profile-1780169301356', 1780858800000, 'Robbie had a good day. He started off the morning playing quietly and was well behaved while he stayed at home with the babysitter, Bella. Around midday, he had quality time with dad, playing baseball in the backyard. He also had good mom bonding time later in the afternoon. In the evening, the whole family went to the outdoor mall in University Village. We ate pizza for dinner, and Robbie played tag outside afterward with Andy, Daisy, and a new friend. He was very helpful cleaning up the playroom when we got home, and as a reward, he was allowed to watch Bluey on TV. He went down for bed easily after taking his medicine.', 1780858800000, 'voice', 1780970809789, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('78af8b35-53e7-4d6e-a102-b952a91e631f', 'profile-1780169301356', 1780807599983, 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', 1780807599983, 'voice', 1780807599983, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('70340fba-4f92-4f3a-973f-e2a0f52a4c36', 'profile-1780169301356', 1780723452298, 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', 1780723452298, 'voice', 1780723452298, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('c97760c6-973c-4898-809b-b09b77a02979', 'profile-1780169301356', 1780599600000, 'Robbie had a good day, went to school, got dressed on his own, played soccer with dad, built blocks with his brother Andy, cleaned up his room, and took his medicine.', 1780599600000, 'voice', 1780708957301, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('0be35a3a-b1bc-4e56-a3ec-d67267b0a882', 'profile-1780169301356', 1780513200000, 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', 1780513200000, 'voice', 1780710076632, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('6c65a05e-c2f9-4e2a-ab50-bdc5cc6e4f3f', 'profile-1780169301356', 1780513200000, 'Robby got into a fight at school and was taken to the principal''s office. We were given a call by the principal afterwards and had a talk with Robby about the incident when we were having dinner.', 1780513200000, 'voice', 1780710228159, 0) ON CONFLICT (id) DO NOTHING;
