INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1781323676516', 'profile-1780169301356', '[{"role":"user","content":"What are Robbie’s verbal strengths?","timestamp":"2026-06-13T04:08:24.427Z"},{"role":"assistant","content":"Robbie has several notable verbal strengths. According to the neuropsychological evaluation conducted by Dr. Marilyn McCune, Robbie demonstrated significant strengths in his verbal comprehension and reasoning abilities. His verbal skills are highlighted by his advanced vocabulary and sophisticated understanding of language. For instance, during the assessment, he was noted to possess a high level of ability to articulate his thoughts and ideas effectively.\n\nAdditionally, his performance on the Wechsler Intelligence Scale for Children (WISC-V) indicated a Verbal Comprehension Index (VCI) score of 124, placing him in the 95th percentile, which is considered above average. This suggests that he can easily grasp complex instructions and understand nuanced concepts presented by the teacher.\n\nFurthermore, Robbie''s expressive language skills are also well-developed. The Vineland-3 assessment indicated that his expressive communication abilities were adequate, and his expressive social communication was rated as high. This suggests that Robbie is capable of engaging in meaningful conversations and expressing himself effectively, particularly when discussing topics of interest, such as his love for drawing and storytelling.\n\nOverall, Robbie''s verbal strengths are characterized by his articulate communication, advanced vocabulary, and ability to engage deeply in discussions, especially around his passions, such as comics and creative storytelling.","timestamp":"2026-06-13T04:08:32.503Z"}]'::jsonb, 1781323676516, 1781323712503, 0, 'What are Robbie’s verbal strengths?') ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1780983570637', 'profile-1780169301356', '[{"role":"user","content":"Tell me about Robbie’s verbal abilities","timestamp":"2026-06-09T05:39:33.026Z"},{"role":"assistant","content":"Robbie has demonstrated notable strengths in his verbal abilities. According to the evaluation conducted by Dr. Marilyn McCune, Robbie possesses advanced verbal comprehension and reasoning abilities, with a Verbal Comprehension Index score of 124, placing him in the 95th percentile, which is considered above average.\n\nDuring his assessments, Robbie showcased a strong vocabulary and the ability to articulate his thoughts effectively. For instance, in the School-Age Language Assessment Measures (SLAM), he scored 8 out of 8 on \"The Crayons\" story task, indicating he could infer complex ideas and articulate them clearly. Additionally, he scored 14.5 out of 16 on \"Bunny Goes to School,\" demonstrating his ability to understand and communicate narratives while using consistent past tense verbs.\n\nHowever, it is noted that Robbie struggles with perspective-taking and may skip context in his storytelling, which can make it challenging for peers to follow along. His pragmatic communication skills were assessed using the Comprehensive Assessment of Spoken Language-2nd Edition (CASL-2), where he received a standard score of 87, indicating average pragmatic language knowledge but highlighting areas for improvement in applying these skills in social interactions.\n\nOverall, Robbie''s verbal abilities are a significant strength, particularly when he is engaged in topics of interest, and with the right support, he can further develop his communication skills to enhance his social interactions.","timestamp":"2026-06-09T05:39:47.393Z"}]'::jsonb, 1780983570637, 1780983587393, 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1780983015243', 'profile-1780169301356', '[{"role":"user","content":"What are some of Robbie’s differences with respect to sensory processing?","timestamp":"2026-06-09T05:36:47.861Z"},{"role":"assistant","content":"Robbie has some unique sensory processing differences that have been observed and reported. For instance, on **10/3/2025**, it was noted that he has challenges with impulse control and emotional regulation, which can lead to difficulties in social interactions and conflicts with peers. His parents shared that when Robbie is dysregulated, he may shut down, refuse tasks, or even become physically aggressive. These episodes are described as a physiological stress response that blocks his participation and connection with others.\n\nAdditionally, Robbie''s occupational therapy evaluation on **10/29/2025** highlighted that he may not consistently recognize or communicate his need for sensory breaks. Instead, he shows signs of dysregulation through changes in behavior, such as becoming withdrawn or irritable. His parents noted that traditional sensory tools, like lap pads and fidgets, have not been effective for him.\n\nDuring observations, Robbie displayed high energy and was easily distracted by peers, indicating that his sensory processing differences might affect his focus and engagement in school settings. He demonstrated some sensory-seeking behaviors, such as hopping around the library and engaging in physical play, but these behaviors did not seem to prevent him from participating in school activities.\n\nOverall, Robbie''s sensory processing differences manifest in his emotional responses, his ability to self-regulate, and his interactions with peers, which are areas that the team is working to support through various strategies and accommodations.","timestamp":"2026-06-09T05:37:00.222Z"}]'::jsonb, 1780983015243, 1780983420222, 0, NULL) ON CONFLICT (id) DO NOTHING;
